corrected_code:
namespace App\Policies;

use App\Models\User;
use App\Models\CrmNote;

class CrmNotePolicy
{
    public function view(User $user, CrmNote $note): bool
    {
        if ($user->organization_id !== $note->organization_id) {
            return false;
        }

        return $note->is_public || $user->id === $note->author_id;
    }
}
